// Persist Canon · Fase 5 · solo tras PASS Camino III
// Escribe brand_book, ICP, análisis competitivo via API.
// RECIÉN AQUÍ se persisten los datos canonizados.

const stagingPkg = $json.staging_package || {};
const clientId = $('Validate Deal Data').first().json.client_id;
const apiUrl = $env.ZERO_RISK_API_URL || 'https://zero-risk-platform.vercel.app';
const apiKey = $env.INTERNAL_API_KEY;

const headers = {
  'Content-Type': 'application/json',
  'x-api-key': apiKey
};

// 1. POST brand_book
let brandBookResult = null;
try {
  const bbResp = await fetch(apiUrl + '/api/clients/' + clientId + '/brand-book', {
    method: 'POST',
    headers: headers,
    body: JSON.stringify({
      brand_book: stagingPkg.brand_book_draft,
      source: 'onboarding_e2e_5phase',
      camino_iii_approved: true,
      approved_at: new Date().toISOString()
    })
  });
  brandBookResult = { status: bbResp.status, ok: bbResp.ok };
} catch(e) {
  brandBookResult = { status: 'error', message: e.message };
}

// 2. POST ICP
let icpResult = null;
try {
  const icpResp = await fetch(apiUrl + '/api/clients/' + clientId + '/icp', {
    method: 'POST',
    headers: headers,
    body: JSON.stringify({
      icp: stagingPkg.icp_draft,
      source: 'onboarding_e2e_5phase',
      camino_iii_approved: true
    })
  });
  icpResult = { status: icpResp.status, ok: icpResp.ok };
} catch(e) {
  icpResult = { status: 'error', message: e.message };
}

// 3. POST competitive analysis al Brain como evidencia CANON (no provisional)
let brainResult = null;
try {
  const brainResp = await fetch(apiUrl + '/api/brain/ingest-source', {
    method: 'POST',
    headers: headers,
    body: JSON.stringify({
      client_id: clientId,
      source_type: 'competitive_intelligence',
      content: JSON.stringify(stagingPkg.competitive_analysis_draft),
      metadata: {
        provenance: 'onboarding_e2e_5phase_post_camino_iii',
        confidence: 'canon',
        type: 'evidencia_canon',
        camino_iii_approved: true,
        approved_at: new Date().toISOString()
      }
    })
  });
  brainResult = { status: brainResp.status, ok: brainResp.ok };
} catch(e) {
  brainResult = { status: 'error', message: e.message };
}

return [{
  json: {
    ...$json,
    persist_canon_results: {
      brand_book: brandBookResult,
      icp: icpResult,
      brain_canon: brainResult,
      persisted_at: new Date().toISOString()
    }
  }
}];

// precisión 3 + fail-safe (consejero 19:19 pt3) · identidad ANTES de promote · contaminación
// imposible de PERSISTIR. Compara el client_id del ARTEFACTO que devolvió el track vs el cliente
// del JOURNEY. Identidad NO VERIFICABLE (artefacto sin client_id / undefined / track ausente) =
// MISMATCH → ABORT → HITL · JAMÁS se promueve (misma clase de bug del 5º: campo ausente ≠ pasa).
const grade = $json.body || $json;                              // respuesta de grade-cimiento
let trackOut = {};
try { trackOut = $('[JEFATURA] Execute Cimiento Track').first().json || {}; } catch (e) { trackOut = {}; }
const journeyClient = String(($('Validate Deal Data').first().json.client_id) || '').trim();
const artifactClient = String((trackOut.client_id) || (trackOut.brand_book_draft && trackOut.brand_book_draft.client_id) || '').trim();
const idVerifiable = journeyClient.length > 0 && artifactClient.length > 0;   // ambos presentes
const idOk = idVerifiable && artifactClient === journeyClient;                // y coinciden
return [{ json: {
  __ABORT: !idOk,                                              // fail-safe: no-verificable ⇒ ABORT
  reason: idOk ? null : (idVerifiable ? 'IDENTIDAD_MISMATCH' : 'IDENTIDAD_NO_VERIFICABLE'),
  journeyClient, artifactClient,
  client_id: journeyClient,
  verdict: grade.verdict || 'UNKNOWN',
  action: idOk ? (grade.action || 'escalate_hitl') : 'abort',
  scores: grade.scores, grounding: grade.grounding, provisional: !!grade.provisional,
  corrections: grade.corrections || [], trace_id: grade.trace_id
} }];

// Cartero · arma el input del creador para la re-síntesis (pass-2 · anti-#255: draft NO se pisa;
// el Consolidador lo re-crea con corrections + _fidelity_cycle). Reusa el input REAL del track.
const trackInput = $("[JEFATURA] Transform discovery→package").first().json || {};
const grade = $json || {};
const corrections = Array.isArray(grade.corrections) ? grade.corrections : [];
return [{ json: Object.assign({}, trackInput, { corrections, _fidelity_cycle: 0 }) }];

